def count(service):
    total = 0
    offset = 0
    while True:
        r = query_logs(service=service, level='ERROR', limit=500, offset=offset)
        lines = r if isinstance(r, list) else r.get('lines', r.get('logs', []))
        total += len(lines)
        if len(lines) < 500:
            break
        offset += 500
    return total

